package cc.crafto.ui.server;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class ProcurementViewTest {
    final UUID town=UUID.randomUUID(),actor=UUID.randomUUID(),id=UUID.randomUUID();
    Map<String,Object> sample(){var r=new HashMap<String,Object>();r.put("project","forge");r.put("targetLevel",1);r.put("building","Кузница");r.put("itemKey","a".repeat(64));r.put("name","Дубовые доски");r.put("amount",272);r.put("rewardCents",2720L);r.put("durationSeconds",86400L);r.put("requestId",id.toString());r.put("contractId",id.toString());r.put("town",town.toString());r.put("actor",actor.toString());r.put("createdAt",1000L);r.put("expiresAt",31000L);r.put("status","QUOTE");r.put("detail","Поставка на общий склад");return r;}
    ProcurementView.Order read(Map<String,Object> r){return ProcurementView.order(r,town,id);}
    @Test void largeAmountsAreNumbersWithoutAnItemStack(){var r=read(sample());assertEquals(272,r.offer().amount());assertEquals(2720,r.offer().cents());assertTrue(r.review(false).contains("Награда из городской казны: 27.2 монет"));}
    @Test void offersCannotReturnAnotherBuilding(){assertThrows(IllegalArgumentException.class,()->ProcurementView.offers(List.of(sample()),"town_hall"));}
    @Test void refusesForeignTownRequestAndContract(){for(String key:List.of("town","requestId","contractId")){var r=sample();r.put(key,UUID.randomUUID().toString());assertThrows(IllegalArgumentException.class,()->read(r),key);}}
    @Test void noDuplicateOffersOrReceipts(){assertThrows(IllegalArgumentException.class,()->ProcurementView.offers(List.of(sample(),sample()),"forge"));assertThrows(IllegalArgumentException.class,()->ProcurementView.orders(List.of(sample(),sample()),town));}
    @Test void limitsBoundEveryProviderList(){assertThrows(IllegalArgumentException.class,()->ProcurementView.offers(Collections.nCopies(46,sample()),"forge"));assertThrows(IllegalArgumentException.class,()->ProcurementView.orders(Collections.nCopies(21,sample()),town));}
    @Test void moneyNeverAcceptsFractionalOrNegativeCents(){for(Object value:List.of(2720.1,-1L,0,100_000_000_001L,"2720")){var r=sample();r.put("rewardCents",value);assertThrows(IllegalArgumentException.class,()->read(r));}}
    @Test void malformedTermsFailClosed(){for(var entry:Map.of("targetLevel",0,"amount",1_000_001,"itemKey","not-an-item","project","forge\ncommand","durationSeconds",59,"expiresAt",999L,"name"," ").entrySet()){var r=sample();r.put(entry.getKey(),entry.getValue());assertThrows(IllegalArgumentException.class,()->read(r),entry.getKey());}}
    @Test void unknownStateNeverLooksPaid(){var r=sample();r.put("status","SUCCESS_MAYBE");assertThrows(IllegalArgumentException.class,()->read(r));}
    @Test void expiredQuoteCannotBePaidButCanBeDiscarded(){var o=read(sample());assertTrue(o.payable(31000));assertFalse(o.payable(31001));assertTrue(o.cancellable());var page=ProcurementView.orderPage(o,31001);assertTrue(page.rows.getFirst().reason().contains("истекла"));}
    @Test void pendingAndFundedAreNeverPresentedAsPublished(){for(String phase:List.of("FUNDING","FUNDED","PUBLISHING")){var r=sample();r.put("status",phase);var o=read(r);assertTrue(o.payable(Long.MAX_VALUE));assertNotEquals("Опубликован в городских контрактах",ProcurementView.status(phase));assertTrue(ProcurementView.orderPage(o,50000).rows.stream().noneMatch(row->row.action()!=null&&row.action().kind().equals("open-contract")));}}
    @Test void publishedOrderCannotUseFullRefundOrRepay(){var r=sample();r.put("status","PUBLISHED");var o=read(r);assertFalse(o.payable(1000));assertFalse(o.cancellable());var page=ProcurementView.orderPage(o,1000);var actions=new HashMap<String,CivicView.Action>();page.json("view",actions,0,12);assertTrue(actions.values().stream().noneMatch(a->a.kind().startsWith("procurement-review-")));assertTrue(actions.values().stream().anyMatch(a->a.kind().equals("open-contract")));}
    @Test void unknownPaymentRequiresAdminReview(){var r=sample();r.put("status","REVIEW");var o=read(r);assertFalse(o.payable(1000));assertFalse(o.cancellable());assertTrue(ProcurementView.status(o.state()).contains("администратора"));}
    @Test void quoteCancellationDoesNotPromiseMoney(){assertTrue(read(sample()).review(true).contains("Возврат оплаченного резерва в казну: 0 монет"));var r=sample();r.put("status","FUNDED");assertTrue(read(r).review(true).contains("Возврат оплаченного резерва в казну: 27.2 монет"));}
    @Test void everyFinancialTermIsBoundToConfirmation(){var original=read(sample()).fingerprint();for(var e:Map.of("amount",271,"rewardCents",2710L,"durationSeconds",3600L,"targetLevel",2,"itemKey","b".repeat(64),"actor",UUID.randomUUID().toString(),"expiresAt",32000L).entrySet()){var r=sample();r.put(e.getKey(),e.getValue());assertNotEquals(original,read(r).fingerprint(),e.getKey());}}
    @Test void receiptProgressAndDescriptionDoNotChangeFrozenTerms(){var r=sample();r.put("status","FUNDED");r.put("detail","Оплачено");assertEquals(read(sample()).fingerprint(),read(r).fingerprint());}
    @Test void fundedPublicationExplainsThereIsNoSecondPayment(){var r=sample();r.put("status","FUNDED");var o=read(r);assertEquals("Опубликовать оплаченный заказ",o.actionTitle());assertTrue(o.review(false).stream().anyMatch(s->s.contains("Уже оплачено")&&s.contains("Повторного списания не будет")));assertEquals("Оплатить заказ",read(sample()).actionTitle());}
    @Test void exactProviderOfferIsUsedForTheAction(){var page=ProcurementView.offersPage(ProcurementView.offers(List.of(sample()),"forge"));var a=page.rows.getFirst().action();assertEquals(new CivicView.Action("procurement-quote","forge","a".repeat(64)),a);assertTrue(page.rows.getFirst().detail().contains("272"));}
    @Test void paginationPreservesServerOwnedOrderIds(){var page=ProcurementView.ordersPage(List.of(read(sample())),2);assertEquals(id.toString(),page.rows.getFirst().action().id());assertEquals("1",page.rows.getLast().action().id());}
    @Test void timeDescriptionDoesNotSilentlyRoundDown(){assertEquals("1 д.",ProcurementView.duration(86400));assertEquals("2 ч.",ProcurementView.duration(7200));assertEquals("90 мин.",ProcurementView.duration(5400));assertEquals("61 сек.",ProcurementView.duration(61));}
}
